import { Formik, Form, Field } from "formik";
import { number, object, string } from "yup";

import "./Input.css";

function Input() {
const validationSchema = object({
    nameSurname: string(),
passNumber: string(),
email: string(),
zip: number(),
age: number(),
})

  return (
    <div>
      <Formik>
        <Form>
          <Field
            type="text"
            placeholder="Name Surname"
            name="nameSurname"
          ></Field>
          <Field
            type="text"
            placeholder="Passport number"
            name="passNumber"
          ></Field>
          <Field type="email" placeholder="Email" name="email"></Field>
          <Field type="number" placeholder="Zip code" name="zip"></Field>
          <Field type="number" placeholder="Age" name="age"></Field>
          <Field type="text" placeholder="Address 1" name="add1"></Field>
          <Field type="text" placeholder="Address 2" name="add2"></Field>
        </Form>
      </Formik>
    </div>
  );
}

export default Input;
